-- 0016_pyq_paper_order.sql
--
-- Serve past papers in the order RPSC printed them.
--
-- 0014 and 0015 loaded the questions but relied on `order by id` to deal them.
-- `id` is a gen_random_uuid() primary key, so that ordering is stable but
-- arbitrary: the 2024 paper opened with Q130 (painting styles), then Q146, then
-- Q73. A mock paper whose questions arrive shuffled is not the paper.
--
-- paper_qno is the question's number on the printed paper. Matched on
-- md5(q) within a year rather than on the stem itself, for the same reason
-- 0007 indexes md5(q): the stems are long enough to be awkward as a key.
--
-- Nulls are expected and fine -- model questions have no paper to be numbered
-- on, and the loader sorts them after the numbered ones.

alter table public.questions add column if not exists paper_qno int;

update public.questions t set paper_qno = v.qno
from (values
